"""Date parsing for invoice imports."""

try:
    from shared.utils import split_date  # platform helper, present in full checkouts
except ImportError:
    def split_date(text):
        """Split a date string into year, month and day strings.

        Supports formats:
        - YYYY-MM-DD (ISO)
        - YYYY/MM/DD (US exports)
        - DD.MM.YYYY (European exports: day first)
        """
        text = text.strip()

        # Try ISO format: YYYY-MM-DD
        if "-" in text:
            parts = text.split("-")
            if len(parts) == 3 and len(parts[0]) == 4:
                year, month, day = parts
                return year, month, day

        # Try slash format: YYYY/MM/DD
        if "/" in text:
            parts = text.split("/")
            if len(parts) == 3 and len(parts[0]) == 4:
                year, month, day = parts
                return year, month, day

        # Try European dotted format: DD.MM.YYYY (day first)
        if "." in text:
            parts = text.split(".")
            if len(parts) == 3 and len(parts[2]) == 4:
                day, month, year = parts
                return year, month, day

        raise ValueError(f"Unrecognized date format: {text}")


def parse_date(text):
    """Parse an import date into a (year, month, day) tuple of ints."""
    year, month, day = split_date(text)
    return (int(year), int(month), int(day))

